<?php
 namespace QQWorld\Store\App\FrontController\Plugin; use \QQWorld\Store\Model\StoreResolver\ReaderList; use \QQWorld\Store\Model\ScopeInterface; class DefaultStore { protected $storeManager; protected $readerList; protected $runMode; protected $scopeCode; public function __construct( \QQWorld\Store\Model\StoreManagerInterface $storeManager, ReaderList $readerList, $runMode = ScopeInterface::SCOPE_STORE, $scopeCode = null ) { $this->runMode = $scopeCode ? $runMode : ScopeInterface::SCOPE_WEBSITE; $this->scopeCode = $scopeCode; $this->readerList = $readerList; $this->storeManager = $storeManager; } public function beforeDispatch( \QQWorld\Framework\App\FrontController $subject, \QQWorld\Framework\App\RequestInterface $request ) { $reader = $this->readerList->getReader($this->runMode); $defaultStoreId = $reader->getDefaultStoreId($this->scopeCode); $this->storeManager->setCurrentStore($defaultStoreId); } } 